-- Pag-Laum Relational Schema & Seed Script for Supabase PostgreSQL
-- Run this in Supabase SQL Editor to mirror or inspect the Django relational tables directly in Supabase.

-- 1. Parent Table: home_app_psychiatriccenter (Main Table - "One" side)
CREATE TABLE IF NOT EXISTS public.home_app_psychiatriccenter (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    slug VARCHAR(50) NOT NULL UNIQUE,
    name VARCHAR(200) NOT NULL,
    city VARCHAR(100) NOT NULL,
    region VARCHAR(100) NOT NULL,
    address TEXT NOT NULL,
    phone VARCHAR(60) NOT NULL,
    dial VARCHAR(60) NOT NULL,
    hours VARCHAR(200) NOT NULL,
    services JSONB NOT NULL DEFAULT '[]'::jsonb,
    lat DOUBLE PRECISION NOT NULL,
    lng DOUBLE PRECISION NOT NULL,
    emergency_available BOOLEAN NOT NULL DEFAULT TRUE
);

-- 2. Child Table: home_app_crisishotline (Related Table - "Many" side with Foreign Key center_id)
CREATE TABLE IF NOT EXISTS public.home_app_crisishotline (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    slug VARCHAR(50) NOT NULL UNIQUE,
    name VARCHAR(200) NOT NULL,
    region VARCHAR(100) NOT NULL,
    category VARCHAR(120) NOT NULL,
    availability VARCHAR(100) NOT NULL DEFAULT '24/7',
    description TEXT NOT NULL,
    numbers JSONB NOT NULL DEFAULT '[]'::jsonb,
    is_featured BOOLEAN NOT NULL DEFAULT FALSE,
    center_id BIGINT NULL REFERENCES public.home_app_psychiatriccenter(id) ON DELETE SET NULL
);

ALTER TABLE public.home_app_crisishotline
    ADD COLUMN IF NOT EXISTS center_id BIGINT NULL REFERENCES public.home_app_psychiatriccenter(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS home_app_crisishotline_center_id_idx
    ON public.home_app_crisishotline(center_id);

-- 3. Episode Guides Table: home_app_episodeguide
CREATE TABLE IF NOT EXISTS public.home_app_episodeguide (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    slug VARCHAR(50) NOT NULL UNIQUE,
    title VARCHAR(200) NOT NULL,
    category VARCHAR(100) NOT NULL,
    urgency VARCHAR(100) NOT NULL,
    duration VARCHAR(60) NOT NULL,
    summary TEXT NOT NULL,
    steps JSONB NOT NULL DEFAULT '[]'::jsonb,
    reassurance TEXT NOT NULL
);

-- 4. Upsert Parent PsychiatricCenter Records (7 rows)
