-- 6. Upsert EpisodeGuide Records (5 rows)
INSERT INTO public.home_app_episodeguide (slug, title, category, urgency, duration, summary, steps, reassurance) VALUES ('panic-attack', 'Panic Attack & Acute Anxiety', 'Anxiety', 'Immediate Calm', '3–5 mins', 'When your heart races, chest tightens, or breathing feels shallow, your nervous system is in a temporary alarm state. These steps help signal safety to your body.', '[{"title": "Pause and plant your feet", "detail": "Sit down if you can. Press both feet flat against the floor and notice the solid surface supporting your weight."}, {"title": "Lengthen your exhale", "detail": "Breathe in gently through your nose for 4 seconds, pause for 2 seconds, and breathe out slowly through pursed lips for 6 seconds."}, {"title": "Drop your shoulders & unclench your jaw", "detail": "Let your shoulders fall away from your ears and rest your tongue gently on the roof of your mouth."}, {"title": "Use cool water or temperature contrast", "detail": "Splash cool water on your face or hold a cold glass in your hands to trigger your body''s natural calming reflex."}, {"title": "Remind yourself it will pass", "detail": "Tell yourself: ''This feeling is uncomfortable, not dangerous. Panic peaks and fades within minutes.''"}]'::jsonb, 'You are safe right now. Take one slow breath at a time.') ON CONFLICT (slug) DO UPDATE SET title=EXCLUDED.title, category=EXCLUDED.category, urgency=EXCLUDED.urgency, duration=EXCLUDED.duration, summary=EXCLUDED.summary, steps=EXCLUDED.steps, reassurance=EXCLUDED.reassurance;
INSERT INTO public.home_app_episodeguide (slug, title, category, urgency, duration, summary, steps, reassurance) VALUES ('sensory-grounding', '5-4-3-2-1 Sensory Grounding', 'Grounding', 'Reset Focus', '2–4 mins', 'Pull your mind out of spiraling thoughts, flashbacks, or dissociation by naming real, neutral things around you right now.', '[{"title": "Notice 5 things you can see", "detail": "Look slowly around the room and name five shapes, colors, or ordinary objects (like a chair, window, or wall texture)."}, {"title": "Notice 4 things you can physically feel", "detail": "Touch the fabric of your shirt, the cool surface of a desk, your hair, or the floor beneath your shoes."}, {"title": "Notice 3 things you can hear", "detail": "Listen for subtle ambient sounds\u2014an electric fan, distant traffic, birds outside, or your own breathing."}, {"title": "Notice 2 things you can smell", "detail": "Notice soap, clean air, coffee, or a comforting scent nearby. Move closer to something fresh if needed."}, {"title": "Notice 1 steady truth or taste", "detail": "Take a sip of water or say aloud one calm truth: ''I am here in this room, and I am taking care of myself.''"}]'::jsonb, 'Your senses bring you back to the present moment where you can take the next small step.') ON CONFLICT (slug) DO UPDATE SET title=EXCLUDED.title, category=EXCLUDED.category, urgency=EXCLUDED.urgency, duration=EXCLUDED.duration, summary=EXCLUDED.summary, steps=EXCLUDED.steps, reassurance=EXCLUDED.reassurance;
INSERT INTO public.home_app_episodeguide (slug, title, category, urgency, duration, summary, steps, reassurance) VALUES ('dark-thoughts', 'Overwhelming Dark Thoughts & Crisis De-escalation', 'Crisis Safety', 'Urgent Safety', 'Immediate', 'When thoughts feel unbearable or unsafe, focus purely on getting through the next 15 minutes and putting distance between yourself and anything harmful.', '[{"title": "Create immediate physical distance", "detail": "Move away from any sharp objects, medications, balconies, or items you could use to hurt yourself. Go to a well-lit shared room if possible."}, {"title": "Do not stay completely alone with the thought", "detail": "Call a crisis hotline (1553 or 0939-937-5433) or message a trusted friend or relative and say: ''I''m having a hard time and need company.''"}, {"title": "Delay major decisions for 24 hours", "detail": "Make a gentle deal with yourself to hold on just for the next hour. Intense emotional storms shift when given time and support."}, {"title": "Focus on one physical anchor", "detail": "Drink a glass of water, wrap yourself in a blanket, or sit near another person even if you don''t feel ready to explain everything."}, {"title": "Go to the nearest emergency psychiatric center if unsafe", "detail": "Use the Psychiatric Centers Map in Pag-Laum to locate the nearest 24/7 behavioral health emergency room or dial 911."}]'::jsonb, 'Your life has value, even when pain makes everything feel heavy. Help is ready to listen without judgment.') ON CONFLICT (slug) DO UPDATE SET title=EXCLUDED.title, category=EXCLUDED.category, urgency=EXCLUDED.urgency, duration=EXCLUDED.duration, summary=EXCLUDED.summary, steps=EXCLUDED.steps, reassurance=EXCLUDED.reassurance;
INSERT INTO public.home_app_episodeguide (slug, title, category, urgency, duration, summary, steps, reassurance) VALUES ('depressive-episode', 'Depressive Episode & Heavy Low Energy', 'Low Mood', 'Gentle Care', '5–10 mins', 'During deep sadness or numbness, even tiny tasks can feel exhausting. Shrink expectations down to gentle, compassionate micro-steps.', '[{"title": "Lower the bar to one tiny action", "detail": "Forget the full to-do list. Pick just one micro-care step: sitting up in bed, opening a curtain, or drinking half a glass of water."}, {"title": "Nourish without pressure", "detail": "If cooking feels impossible, eat something simple like crackers, fruit, bread, or warm soup\u2014any nourishment counts."}, {"title": "Get 2 minutes of natural light or fresh air", "detail": "Stand near an open window or step outside briefly. Natural light helps gently regulate mood and sleep signals."}, {"title": "Silence harsh self-criticism", "detail": "Speak to yourself the way you would to a tired friend: ''I''m carrying a lot right now, and resting is not laziness.''"}, {"title": "Send a low-effort check-in", "detail": "Text someone safe even a single message like ''Low energy today, just checking in'' so you stay gently connected."}]'::jsonb, 'Doing one small thing today is more than enough.') ON CONFLICT (slug) DO UPDATE SET title=EXCLUDED.title, category=EXCLUDED.category, urgency=EXCLUDED.urgency, duration=EXCLUDED.duration, summary=EXCLUDED.summary, steps=EXCLUDED.steps, reassurance=EXCLUDED.reassurance;
INSERT INTO public.home_app_episodeguide (slug, title, category, urgency, duration, summary, steps, reassurance) VALUES ('helping-someone', 'Helping Someone Experiencing an Episode', 'Caregiver Guide', 'Supportive Action', 'Ongoing', 'If a friend, classmate, or family member is panicking or in distress, your calm presence matters far more than having perfect answers.', '[{"title": "Stay calm and speak softly", "detail": "Use a warm, steady tone and simple sentences. Avoid crowding them or raising your voice."}, {"title": "Validate without arguing or minimizing", "detail": "Say: ''I''m right here with you. You don''t have to rush.'' Avoid phrases like ''Just calm down'' or ''Others have it worse.''"}, {"title": "Ask what feels helpful right now", "detail": "Offer concrete choices: ''Would you like water, a quieter space, or for me to breathe slowly with you?''"}, {"title": "Assess immediate safety gently", "detail": "If they mention wanting to harm themselves, stay with them, keep hazardous items away, and call a crisis hotline together."}, {"title": "Connect to professional support", "detail": "Help them dial a 24/7 hotline or accompany them to the nearest psychiatric emergency unit using the Pag-Laum Centers Map."}]'::jsonb, 'Sitting beside someone in the dark is one of the most powerful acts of care.') ON CONFLICT (slug) DO UPDATE SET title=EXCLUDED.title, category=EXCLUDED.category, urgency=EXCLUDED.urgency, duration=EXCLUDED.duration, summary=EXCLUDED.summary, steps=EXCLUDED.steps, reassurance=EXCLUDED.reassurance;

